// Logs → Streams tab — the RAW streams, their inventory and retention, AS GRAPH SOURCE (epic #3604).
//
// The last tab of the Logs workspace, and the only one that MOVES an existing surface rather than
// building a new one. Three cards lived on Settings → Planner under "Storage & logs": the inventory,
// a raw tail viewer, and the retention caps. They belong here — they ARE the logs, and a settings
// page is where you configure a thing, not where you read it. They are removed from Settings in the
// same change; two copies of a log viewer is how this repo accumulates the drift it keeps paying for.
//
// AN ABSENT STREAM MUST READ AS ABSENT, NOT AS AN EMPTY ONE. That distinction is the tab's real
// value, not a nicety: measured, 3 of the 10 canonical streams have no file at all (`mcp`, `hook`,
// `done`), and answering "has this emitter ever fired?" by hand is what decided the Hooks tab was not
// worth building (`the-logs-hooks-tab-has-no-data-to-show`). A screen that showed those three as
// "0 bytes" would have hidden the very thing worth knowing.
//
// Preview note: the file-info type and the invoke bridge are app-internal (unresolvable in this
// sandbox), so the type and a sample inventory are inlined and every action is a no-op prop by
// default. Every prop still overrides the sample when composed by LogsWorkspace.
import { StatTile } from "@/shared/ui/data/StatTile";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { SelectField } from "@/shared/ui/controls/Field";
import { ConfirmButton } from "@/shared/ui/controls/ConfirmButton";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

/** One managed stream on disk — the `LogFileInfo` shape. camelCase on the wire (it DOES carry
 *  `serde(rename_all)`, unlike `SessionRow` and `Cost` in the logs crate). */
interface LogFileInfo {
  stream: string; label: string; path: string;
  sizeBytes: number; mtimeMs: number; exists: boolean; text: boolean;
}

/** Retention caps. 0 means "no cap" for either. */
interface LogCaps { maxLines: number; maxSizeMb: number }

const NOW = 1700000000000;
const SAMPLE_FILES: LogFileInfo[] = [
  { stream: "app", label: "Application log", path: "…/base-studio-code.log", sizeBytes: 4_200_000, mtimeMs: NOW - 60000, exists: true, text: true },
  { stream: "tool", label: "Tool attempts", path: "…/audit.log", sizeBytes: 2_127_295, mtimeMs: NOW - 300000, exists: true, text: true },
  { stream: "coord", label: "Coordination", path: "…/coord.log", sizeBytes: 124_895, mtimeMs: NOW - 86_400_000, exists: true, text: true },
  { stream: "mcp", label: "MCP calls", path: "…/mcp.log", sizeBytes: 0, mtimeMs: 0, exists: false, text: true },
  { stream: "hook", label: "Hook outcomes", path: "…/hooks.log", sizeBytes: 0, mtimeMs: 0, exists: false, text: true },
  { stream: "perf", label: "Performance", path: "…/perf.db", sizeBytes: 810_000, mtimeMs: NOW - 900000, exists: true, text: false },
];

/** ANSI SGR escapes — the app log is written with colour and it is noise in a plain <pre>. */
const ANSI = /\x1b\[[0-9;]*m/g; // eslint-disable-line no-control-regex
/** Levels the app log tags its lines with; only that stream gets the filter. */
export const LOG_LEVELS = ["ERROR", "WARN", "INFO", "DEBUG", "TRACE"];

/** `4.2 MB` / `124.9 KB` / `810 B`. An ABSENT file is not "0 B" — see `streamState`. */
export function fmtSize(bytes: number): string {
  const v = Number.isFinite(bytes) ? bytes : 0;
  if (v >= 1e6) return (v / 1e6).toFixed(1) + " MB";
  if (v >= 1e3) return (v / 1e3).toFixed(1) + " KB";
  return v + " B";
}

/** How long since the stream was last written. `mtimeMs` is 0 when the file is absent. */
export function lastWrite(mtimeMs: number, now: number): string {
  if (!mtimeMs) return "never";
  const m = Math.floor(Math.max(0, now - mtimeMs) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return m + "m ago";
  const h = Math.floor(m / 60);
  if (h < 24) return h + "h ago";
  return Math.floor(h / 24) + "d ago";
}

/**
 * The THREE states a stream can be in, which a size alone cannot express:
 *
 *   `absent`  — no file. The emitter has never fired. THIS IS THE ONE THAT MATTERS.
 *   `empty`   — the file exists but holds nothing: it fired, then was cleared or trimmed to nothing.
 *   `present` — has content.
 *
 * Collapsing `absent` into `empty` is exactly the mistake that made the Hooks question expensive.
 */
export function streamState(f: LogFileInfo): "absent" | "empty" | "present" {
  if (!f.exists) return "absent";
  return f.sizeBytes === 0 ? "empty" : "present";
}

/** Strip ANSI, then filter by substring and (app log only) level. Pure so the filter is testable. */
export function filterLines(lines: string[], search: string, level: string, isAppLog: boolean): string[] {
  const q = search.trim().toLowerCase();
  return lines
    .map((l) => l.replace(ANSI, ""))
    .filter((l) => (q === "" || l.toLowerCase().includes(q)) && (!isAppLog || level === "all" || l.includes(level)));
}

/** Totals for the tiles — and the count of streams that have never been written, which is the
 *  headline fact this tab exists to make visible. */
export function inventoryTotals(files: LogFileInfo[]) {
  return {
    streams: files.length,
    present: files.filter((f) => streamState(f) === "present").length,
    absent: files.filter((f) => streamState(f) === "absent").length,
    bytes: files.reduce((n, f) => n + (f.exists ? f.sizeBytes : 0), 0),
  };
}

const STATE_STYLE: Record<string, { label: string; color: string }> = {
  present: { label: "", color: "var(--success)" },
  empty: { label: "empty", color: "var(--state-wait)" },
  absent: { label: "no file", color: "var(--fg-dim)" },
};

export interface StreamsTabProps {
  files?: LogFileInfo[];
  caps?: LogCaps;
  setCaps?: (c: LogCaps) => void;
  onEnforce?: () => void;
  onClear?: (stream: string) => void;
  /** The stream whose tail is open, or null. */
  selected?: string | null;
  onSelect?: (stream: string | null) => void;
  /** Raw tail of the selected stream, oldest-first as `read_log_tail` returns it. */
  lines?: string[];
  search?: string;
  setSearch?: (s: string) => void;
  level?: string;
  setLevel?: (s: string) => void;
  loaded?: boolean;
  now?: number;
}

export function StreamsTab({
  files = SAMPLE_FILES, caps = { maxLines: 10000, maxSizeMb: 10 }, setCaps = () => {},
  onEnforce = () => {}, onClear = () => {},
  selected = null, onSelect = () => {},
  lines = [], search = "", setSearch = () => {}, level = "all", setLevel = () => {},
  loaded = true, now = NOW,
}: StreamsTabProps) {
  const t = inventoryTotals(files);
  const isAppLog = selected === "app";
  const shown = filterLines(lines, search, level, isAppLog);
  const sel = files.find((f) => f.stream === selected) ?? null;

  const COLS = "1.3fr 96px 92px 96px 128px";
  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="streams" v={t.streams} sub="managed log files" />
        <StatTile k="with data" v={t.present} tone="success" sub="have been written" />
        <StatTile k="never written" v={t.absent} tone={t.absent > 0 ? "accent" : undefined} sub="emitter has not fired" />
        <StatTile k="on disk" v={fmtSize(t.bytes)} sub="total, before trimming" />
      </Box>

      {files.length === 0 ? (
        <EmptyState
          iconVariant="dashed" icon="▤" size="sm"
          title={loaded ? "No managed streams" : "Reading the log directory…"}
          description="Every telemetry stream the app writes appears here with its size, last write and retention."
        />
      ) : (
        <>
          <Box border="soft" radius={7} style={{ overflow: "hidden", marginBottom: 16 }}>
            <Box style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
              <Box as="span">stream</Box>
              <Box as="span" style={{ textAlign: "right" }}>size</Box>
              <Box as="span" style={{ textAlign: "right" }}>last write</Box>
              <Box as="span" />
              <Box as="span" />
            </Box>
            {files.map((f, i) => {
              const st = streamState(f);
              const style = STATE_STYLE[st];
              return (
                <Box key={f.stream} style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, alignItems: "center", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)", opacity: st === "absent" ? 0.6 : 1 }}>
                  <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 7, minWidth: 0 }}>
                    <Box as="span" bg={style.color} radius={99} style={{ width: 6, height: 6, flex: "0 0 auto" }} />
                    <Text as="span" mono size={11} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{f.label}</Text>
                    <Text as="span" mono size={10} tone="dim">{f.stream}</Text>
                  </Box>
                  {/* An absent stream shows its STATE where a size would go. "0 B" would say the file
                      exists and is empty, which is a different — and less useful — fact. */}
                  {st === "present" ? (
                    <Text as="span" mono size={10.5} tone="muted" style={{ textAlign: "right" }}>{fmtSize(f.sizeBytes)}</Text>
                  ) : (
                    <Text as="span" mono size={10.5} style={{ textAlign: "right", color: style.color, fontStyle: "italic" }}>{style.label}</Text>
                  )}
                  <Text as="span" mono size={10.5} tone="dim" style={{ textAlign: "right" }}>{lastWrite(f.mtimeMs, now)}</Text>
                  <Row justify="end">
                    {f.text && f.exists && (
                      <Button size="sm" variant="ghost" onClick={() => onSelect(selected === f.stream ? null : f.stream)}>
                        {selected === f.stream ? "hide" : "view"}
                      </Button>
                    )}
                  </Row>
                  <Row justify="end">
                    {/* Clearing is destructive and irreversible; it keeps its confirm step. */}
                    {f.exists && f.sizeBytes > 0 && (
                      <ConfirmButton size="sm" label="clear" armedLabel="clear?" onConfirm={() => onClear(f.stream)} />
                    )}
                  </Row>
                </Box>
              );
            })}
          </Box>

          {sel && (
            <Box style={{ marginBottom: 16 }}>
              <Row align="center" gap={10} wrap style={{ marginBottom: 8 }}>
                <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em" }}>{sel.label}</Text>
                <SearchField value={search} onChange={setSearch} placeholder="filter lines…" style={{ width: 220 }} />
                {isAppLog && (
                  <SelectField style={{ width: 120 }} value={level} onChange={setLevel}>
                    <option value="all">all levels</option>
                    {LOG_LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
                  </SelectField>
                )}
                <Box style={{ flex: 1 }} />
                <Text as="span" mono size={10} tone="dim">{shown.length} of {lines.length} lines</Text>
                <Button size="sm" variant="ghost" onClick={() => onSelect(null)}>close</Button>
              </Row>
              <Box border="soft" radius={7} style={{ background: "var(--bg-panel)", maxHeight: 360, overflow: "auto", padding: "8px 12px" }}>
                {shown.length === 0 ? (
                  <Text as="div" mono size={11} tone="dim">
                    {lines.length === 0 ? "This stream is empty." : "No line matches the filter."}
                  </Text>
                ) : shown.map((l, i) => (
                  <Text key={i} as="div" mono size={10.5} tone="muted" style={{ whiteSpace: "pre-wrap", wordBreak: "break-all", lineHeight: 1.5 }}>{l}</Text>
                ))}
              </Box>
            </Box>
          )}

          <Text as="div" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em", marginBottom: 7 }}>retention</Text>
          <Box border="soft" radius={7} style={{ padding: "12px 14px" }}>
            <Row align="center" gap={12} wrap>
              <Text as="span" size={11.5} tone="muted">Trim each stream to its newest</Text>
              <SelectField style={{ width: 130 }} value={String(caps.maxLines)} onChange={(v) => setCaps({ ...caps, maxLines: Number(v) })}>
                <option value="0">no line cap</option>
                <option value="1000">1,000 lines</option>
                <option value="5000">5,000 lines</option>
                <option value="10000">10,000 lines</option>
                <option value="50000">50,000 lines</option>
              </SelectField>
              <Text as="span" size={11.5} tone="muted">or</Text>
              <SelectField style={{ width: 120 }} value={String(caps.maxSizeMb)} onChange={(v) => setCaps({ ...caps, maxSizeMb: Number(v) })}>
                <option value="0">no size cap</option>
                <option value="5">5 MB</option>
                <option value="10">10 MB</option>
                <option value="50">50 MB</option>
              </SelectField>
              <Box style={{ flex: 1 }} />
              <Button size="sm" onClick={onEnforce}>enforce now</Button>
            </Row>
            <Text as="div" size={11} tone="dim" style={{ marginTop: 9, lineHeight: 1.55 }}>
              Caps apply on enforcement and at startup. Trimming keeps the NEWEST lines, so history is
              lost from the oldest end — the rollups on the other tabs re-derive from whatever remains.
            </Text>
          </Box>
        </>
      )}
    </Box>
  );
}

