// The Logs → Streams tab — inventory, raw tail, retention.
//
// Carried ON the record, so it runs against the copy that actually mounts.
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import {
  StreamsTab, streamState, filterLines, inventoryTotals, fmtSize, lastWrite,
} from "./StreamsTab";

const NOW = 1700000000000;
const MIN = 60000;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;

const FILES = [
  { stream: "app", label: "Application log", path: "a", sizeBytes: 4200000, mtimeMs: NOW - MIN, exists: true, text: true },
  { stream: "coord", label: "Coordination", path: "c", sizeBytes: 124895, mtimeMs: NOW - DAY, exists: true, text: true },
  // The file exists but was cleared — DIFFERENT from never having been written.
  { stream: "perm", label: "Permissions", path: "p", sizeBytes: 0, mtimeMs: NOW - HOUR, exists: true, text: true },
  // No file at all: the emitter has never fired. This is the case the tab exists to surface.
  { stream: "hook", label: "Hook outcomes", path: "h", sizeBytes: 0, mtimeMs: 0, exists: false, text: true },
  { stream: "perf", label: "Performance", path: "pf", sizeBytes: 810000, mtimeMs: NOW - MIN, exists: true, text: false },
];

describe("streamState — the distinction the tab is for", () => {
  it("separates ABSENT from EMPTY, which a size alone cannot", () => {
    expect(streamState(FILES[3])).toBe("absent");  // no file
    expect(streamState(FILES[2])).toBe("empty");   // file, zero bytes
    expect(streamState(FILES[1])).toBe("present");
  });

  it("an absent stream is absent even if a size somehow came through", () => {
    // `exists` is the authority; a stale size must not promote a missing file to a real one.
    expect(streamState({ ...FILES[3], sizeBytes: 999 })).toBe("absent");
  });
});

describe("inventoryTotals", () => {
  it("counts never-written streams and excludes them from the byte total", () => {
    const t = inventoryTotals(FILES);
    expect(t.streams).toBe(5);
    expect(t.present).toBe(3);
    expect(t.absent).toBe(1);
    expect(t.bytes).toBe(4200000 + 124895 + 0 + 810000);
  });
});

describe("fmtSize / lastWrite", () => {
  it("scales bytes and never renders NaN", () => {
    expect(fmtSize(4200000)).toBe("4.2 MB");
    expect(fmtSize(124895)).toBe("124.9 KB");
    expect(fmtSize(810)).toBe("810 B");
    expect(fmtSize(NaN)).toBe("0 B");
  });

  it("reads an absent file's zero mtime as NEVER, not as 1970", () => {
    // The single most misleading thing this could render: `mtimeMs` is 0 when the file is absent,
    // and a naive date format turns that into "Jan 1 1970" or "56y ago".
    expect(lastWrite(0, NOW)).toBe("never");
    expect(lastWrite(NOW - MIN * 5, NOW)).toBe("5m ago");
    expect(lastWrite(NOW - HOUR * 3, NOW)).toBe("3h ago");
    expect(lastWrite(NOW - DAY * 2, NOW)).toBe("2d ago");
  });

  it("clamps a future mtime rather than rendering a negative age", () => {
    expect(lastWrite(NOW + HOUR, NOW)).toBe("just now");
  });
});

describe("filterLines", () => {
  const LINES = [
    "[32mINFO[0m started the pump",
    "[31mERROR[0m the pump died",
    "DEBUG polled once",
  ];

  it("strips ANSI so the escapes are not searchable noise", () => {
    const out = filterLines(LINES, "", "all", true);
    expect(out[0]).toBe("INFO started the pump");
    expect(out.join("")).not.toContain("");
  });

  it("searches the CLEANED text, so a colour code cannot break a match", () => {
    // Searching the raw line for "INFO started" would miss — the escape sits between them.
    expect(filterLines(LINES, "INFO started", "all", true)).toHaveLength(1);
  });

  it("is case-insensitive and ignores surrounding whitespace in the query", () => {
    expect(filterLines(LINES, "  PUMP  ", "all", true)).toHaveLength(2);
  });

  it("applies the level filter ONLY to the app log", () => {
    expect(filterLines(LINES, "", "ERROR", true)).toHaveLength(1);
    // Another stream's lines have no levels; filtering them would silently empty the view.
    expect(filterLines(LINES, "", "ERROR", false)).toHaveLength(3);
  });
});

describe("StreamsTab", () => {
  it("marks a never-written stream as such instead of showing 0 B", () => {
    render(<StreamsTab files={FILES} now={NOW} />);
    // The ROW says "no file" (a fact about disk); the TILE says "never written" (a count of them).
    // They deliberately do not share wording — two identical labels meaning different things on one
    // screen is how a reader mistakes a per-stream state for a fleet-wide one.
    expect(screen.getByText("no file")).toBeInTheDocument();
    expect(screen.getByText("never")).toBeInTheDocument(); // its last-write cell
  });

  it("distinguishes a cleared stream from a never-written one", () => {
    render(<StreamsTab files={FILES} now={NOW} />);
    expect(screen.getByText("empty")).toBeInTheDocument();
    expect(screen.getByText("1h ago")).toBeInTheDocument(); // the cleared one WAS written
  });

  it("counts the never-written streams on a tile", () => {
    render(<StreamsTab files={FILES} now={NOW} />);
    expect(screen.getByText("never written")).toBeInTheDocument();
    expect(screen.getByText("emitter has not fired")).toBeInTheDocument();
  });

  it("offers no view button for a binary stream or a missing file", () => {
    render(<StreamsTab files={FILES} now={NOW} />);
    // app + coord + perm are text and exist; perf is binary, hook is absent.
    expect(screen.getAllByText("view")).toHaveLength(3);
  });

  it("offers no clear for an empty or absent stream — there is nothing to clear", () => {
    render(<StreamsTab files={FILES} now={NOW} />);
    expect(screen.getAllByText("clear")).toHaveLength(3); // app, coord, perf
  });

  it("reports the selection instead of opening the viewer itself", () => {
    const onSelect = vi.fn();
    render(<StreamsTab files={FILES} onSelect={onSelect} now={NOW} />);
    fireEvent.click(screen.getAllByText("view")[0]);
    expect(onSelect).toHaveBeenCalledWith("app");
  });

  it("shows the level filter for the app log and NOT for another stream", () => {
    const { rerender } = render(<StreamsTab files={FILES} selected="app" lines={["INFO x"]} now={NOW} />);
    expect(screen.getByText("all levels")).toBeInTheDocument();
    rerender(<StreamsTab files={FILES} selected="coord" lines={["a b c"]} now={NOW} />);
    expect(screen.queryByText("all levels")).toBeNull();
  });

  it("says whether a viewer is empty because the stream is, or because the filter is", () => {
    // Two very different facts that both render as no rows.
    const { rerender } = render(<StreamsTab files={FILES} selected="coord" lines={[]} now={NOW} />);
    expect(screen.getByText("This stream is empty.")).toBeInTheDocument();
    rerender(<StreamsTab files={FILES} selected="coord" lines={["abc"]} search="zzz" now={NOW} />);
    expect(screen.getByText("No line matches the filter.")).toBeInTheDocument();
  });

  it("clearing requires a confirm step", () => {
    const onClear = vi.fn();
    render(<StreamsTab files={FILES} onClear={onClear} now={NOW} />);
    fireEvent.click(screen.getAllByText("clear")[0]);
    expect(onClear).not.toHaveBeenCalled();          // armed, not fired
    fireEvent.click(screen.getByText("clear?"));
    expect(onClear).toHaveBeenCalledWith("app");
  });

  it("reports a retention change rather than applying it itself", () => {
    const setCaps = vi.fn();
    render(<StreamsTab files={FILES} caps={{ maxLines: 10000, maxSizeMb: 10 }} setCaps={setCaps} now={NOW} />);
    fireEvent.change(screen.getByDisplayValue("10,000 lines"), { target: { value: "1000" } });
    expect(setCaps).toHaveBeenCalledWith({ maxLines: 1000, maxSizeMb: 10 });
  });

  it("an empty inventory is an empty STATE, and loading says loading", () => {
    const { rerender } = render(<StreamsTab files={[]} loaded now={NOW} />);
    expect(screen.getByText("No managed streams")).toBeInTheDocument();
    rerender(<StreamsTab files={[]} loaded={false} now={NOW} />);
    expect(screen.getByText("Reading the log directory…")).toBeInTheDocument();
  });
});
